__device__ __forceinline__ float4 ldg_realigned4(
    const float* __restrict__ X,
    int64_t row_base,
    int q,
    int64_t total_f)
{
  const int s = (int)(row_base & 3LL);
  const float4* p4 = reinterpret_cast<const float4*>(X + (row_base & ~3LL)) + q;
  const float4 v0 = __ldcs(p4);
  if (s == 0) {
    return v0;
  }
  const int64_t g = (row_base & ~3LL) + (((int64_t)q) << 2) + 4;
  float4 v1 = make_float4(-CUDART_INF_F, -CUDART_INF_F, -CUDART_INF_F, -CUDART_INF_F);
  if (g < total_f) {
    v1 = __ldcs(p4 + 1);
  }
  if (s == 1) return make_float4(v0.y, v0.z, v0.w, v1.x);
  if (s == 2) return make_float4(v0.z, v0.w, v1.x, v1.y);
  return make_float4(v0.w, v1.x, v1.y, v1.z);
}
