class ModelNew(nn.Module):
    """
    Max reduction over a specific dimension using a single custom CUTE/CUDA kernel.
    For the provided case (dim=1 on [B, M, N]), this reduces over M while keeping
    coalesced accesses across the contiguous N dimension.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = int(dim)
        self._ext = max_reduce_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.max_reduce_dim(x, self.dim)

